html:
{%- set sscc = doc.name -%}
{%- set ps_items = frappe.get_all('Packing Slip Item', filters={'ucc128': sscc}, fields=['name', 'parent', 'parcel_number', 'item_code', 'item_name', 'qty', 'parcel_details'], order_by='idx', limit=1) -%}
{%- if ps_items -%}
  {%- set psi = ps_items[0] -%}
  {%- set ps = frappe.get_doc('Packing Slip', psi.parent) -%}
  {%- set parcel_number = psi.parcel_number -%}
  {%- set all_parcel_items = frappe.get_all('Packing Slip Item', filters={'parent': psi.parent, 'parcel_number': parcel_number}, fields=['item_code', 'item_name', 'qty', 'stock_uom', 'parcel_details'], order_by='idx') -%}
  {%- set ship_to = frappe.get_doc('Address', ps.shipping_address_name) if ps.shipping_address_name else none -%}
  {%- set ship_from = frappe.get_doc('Address', ps.dispatch_address_name) if ps.dispatch_address_name else none -%}
{%- else -%}
  {%- set ps = none -%}
  {%- set psi = none -%}
  {%- set all_parcel_items = [] -%}
  {%- set ship_to = none -%}
  {%- set ship_from = none -%}
  {%- set parcel_number = none -%}
{%- endif -%}

<meta name="pdfkit-orientation" content="Portrait"/>
<div class="sscc-label">

  <div class="address-row">
    {%- if ship_from %}
    <div class="address-block from-block">
      <div class="block-label">FROM</div>
      {%- if ship_from.company %}<div class="addr-name">{{ ship_from.company }}</div>{%- endif %}
      <div>{{ ship_from.address_line1 or '' }}</div>
      {%- if ship_from.address_line2 %}<div>{{ ship_from.address_line2 }}</div>{%- endif %}
      <div>{{ ship_from.city }}{%- if ship_from.state %}, {{ ship_from.state }}{%- endif %} {{ ship_from.pincode or '' }}</div>
    </div>
    {%- endif %}
    {%- if ship_to %}
    <div class="address-block to-block">
      <div class="block-label">SHIP TO</div>
      <div class="addr-name">{{ (ship_to.address_title or '').split('-')[0].strip() }}</div>
      <div>{{ ship_to.address_line1 or '' }}</div>
      {%- if ship_to.address_line2 %}<div>{{ ship_to.address_line2 }}</div>{%- endif %}
      <div>{{ ship_to.city }}{%- if ship_to.state %}, {{ ship_to.state }}{%- endif %} {{ ship_to.pincode or '' }}</div>
    </div>
    {%- endif %}
  </div>

  {%- if all_parcel_items %}
  <div class="contents-section">
    <div class="section-header">CONTENTS
      {%- if parcel_number %} &mdash; PARCEL {{ parcel_number }}{%- endif %}
      {%- if ps %} &mdash; {{ ps.name }}{%- endif %}
    </div>
    <table class="contents-table">
      <thead>
        <tr><th class="col-item">Item</th><th class="col-qty">Qty</th></tr>
      </thead>
      <tbody>
        {%- for item in all_parcel_items %}
        <tr>
          <td>{{ item.item_name or item.item_code }}</td>
          <td class="col-qty">{{ item.qty | int }}{% if item.stock_uom %} {{ item.stock_uom }}{% endif %}</td>
        </tr>
        {%- endfor %}
      </tbody>
    </table>
    {%- if all_parcel_items[0].parcel_details %}
    <div class="parcel-dims">{{ all_parcel_items[0].parcel_details }}</div>
    {%- endif %}
  </div>
  {%- endif %}

  <div class="barcode-section">
    <div class="barcode-ai">(00)</div>
    <div class="barcode-img">{{ barcode128(doc.name) }}</div>
    <div class="barcode-text">{{ doc.name }}</div>
  </div>

</div>

<style>
@media screen, print {
  .sscc-label {
    font-family: Helvetica, Arial, sans-serif;
    font-size: 9pt;
    width: 4in;
    min-height: 5.5in;
    padding: 3mm;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
  }
  .address-row {
    display: flex;
    gap: 3mm;
    margin-bottom: 3mm;
    padding-bottom: 2mm;
    border-bottom: 1pt solid black;
  }
  .address-block {
    flex: 1;
    font-size: 8pt;
    line-height: 1.4;
  }
  .to-block {
    flex: 1.4;
  }
  .block-label {
    font-size: 6.5pt;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.5pt;
    color: #444;
    margin-bottom: 0.5mm;
  }
  .addr-name {
    font-weight: bold;
  }
  .section-header {
    font-size: 7.5pt;
    font-weight: bold;
    text-transform: uppercase;
    border-bottom: 0.5pt solid black;
    padding-bottom: 1mm;
    margin-bottom: 1.5mm;
  }
  .contents-section {
    flex: 1;
    margin-bottom: 3mm;
  }
  .contents-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 8pt;
  }
  .contents-table th {
    text-align: left;
    font-size: 7pt;
    padding: 0.5mm 1mm;
    border-bottom: 0.5pt solid #aaa;
  }
  .contents-table td {
    padding: 0.5mm 1mm;
    vertical-align: top;
  }
  .col-qty {
    text-align: right;
    white-space: nowrap;
    width: 25%;
  }
  .parcel-dims {
    font-size: 7pt;
    color: #555;
    margin-top: 2mm;
    font-style: italic;
  }
  .barcode-section {
    margin-top: auto;
    padding-top: 3mm;
    border-top: 1pt solid black;
    text-align: center;
  }
  .barcode-ai {
    font-size: 8pt;
    font-weight: bold;
    margin-bottom: 1mm;
  }
  .barcode-img img {
    width: 3.5in;
    height: 0.75in;
    display: block;
    margin: 0 auto;
  }
  .barcode-text {
    font-family: 'Courier New', Courier, monospace;
    font-size: 9pt;
    font-weight: bold;
    letter-spacing: 1.5pt;
    margin-top: 1.5mm;
  }
}
</style>
